select n.id as id from notes n  left join study_packs sp on sp.note_id = n.id  left join (select rank_copy_n.copied_from_note_id as note_id, count(*) as metric from notes rank_copy_n where rank_copy_n.copied_from_public = true and rank_copy_n.copied_from_note_id is not null group by rank_copy_n.copied_from_note_id) rank_copies on rank_copies.note_id = n.id  left join (select rank_like.note_id as note_id, count(*) as metric from public_note_likes rank_like group by rank_like.note_id) rank_likes on rank_likes.note_id = n.id  left join (select rank_view.entity_id as note_id, count(*) as metric from analytics_events rank_view where rank_view.event_type = 'PUBLIC_NOTE_VIEWED' and rank_view.entity_id is not null group by rank_view.entity_id) rank_views on rank_views.note_id = n.id  where n.visibility = 'PUBLIC' and (
    n.status = 'GENERATED'
    or (
        (n.status is null or n.status = 'DRAFT')
        and exists (select 1 from study_packs ready_sp where ready_sp.note_id = n.id)
    )
) and (sp.summary is not null and trim(sp.summary) <> '') and (n.content is not null and trim(n.content) <> '') and case when sp.quiz is null or trim(cast(sp.quiz as varchar)) in ('', '[]', 'null') then 0 else 1 end > 0  order by (cast(coalesce(rank_copies.metric, 0) * 3 + coalesce(rank_likes.metric, 0) * 2 + coalesce(rank_views.metric, 0) * 1 as double precision) * greatest(cast(1 as double precision) / (cast(1 as double precision) + greatest(cast(0 as double precision), cast(floor(cast(datediff(second, n.created_at, cast(? as timestamp with time zone)) as double precision) / 86400) as double precision)) / cast(30.0 as double precision)), cast(0.1 as double precision))) desc, coalesce(rank_copies.metric, 0) desc, coalesce(rank_views.metric, 0) desc, n.created_at desc, n.id asc fetch first ? rows only